// Fired when N8N-A02 crashes.
// Builds HMAC-signed S03 anomaly alert.
// No request_id available cross-workflow — Mark as failed targets all stuck rows by status.
const crypto = require('crypto');
const SECRET = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';
const e = $json;

const makeUUID = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});

const failureMsg = String(e.execution?.error?.message || 'workflow_error').slice(0, 500);

const body = JSON.stringify({
  anomaly_id:   makeUUID(),
  anomaly_type: 'n8n_failure',
  severity:     'error',
  source_flow:  'N8N-A02',
  brand_id:     null,
  message:      failureMsg,
  details: {
    failed_node:  e.execution?.lastNodeExecuted ?? null,
    error_name:   e.execution?.error?.name      ?? null,
    execution_id: e.execution?.id               ?? null,
  },
  timestamp: new Date().toISOString(),
});

const sig = crypto.createHmac('sha256', SECRET).update(body).digest('hex');
return [{
  json: {
    _body: body,
    _headers: {
      'content-type':     'application/json',
      'x-n8n-signature':  sig,
      'x-n8n-request-id': `${$execution.id}-err-a02`,
      'x-n8n-timestamp':  new Date().toISOString(),
    },
    _failure_reason: failureMsg,
  }
}];
